	async forgetPassword(identifier, verifyPhone, newPassword) {
		const data = await (await apiFetch("/api/auth/forget-password", {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				identifier,
				verifyPhone,
				newPassword
			})
		})).json();
		if (!data.success) throw new Error(data.message || "पासवर्ड रीसेट असफल");
		return data;
	},
	async verifySession(userId) {
		const sessionToken = this.getStoredSessionToken();
		const query = new URLSearchParams();
		if (sessionToken) query.set("token", sessionToken);
		if (userId) query.set("userId", userId);
		const data = await (await apiFetch(`/api/auth/verify-session?${query.toString()}`, { headers: { "x-session-token": sessionToken } })).json();
		if (data.valid && data.user) this.setStoredUser(data.user, sessionToken);
		return data;
	},
	async getUserDashboard(userId) {
		const sessionToken = this.getStoredSessionToken();
		const data = await (await apiFetch(`/api/user/${userId}`, { headers: { "x-session-token": sessionToken } })).json();
		if (!data.success) throw new Error(data.message || "Failed to load user dashboard");
		if (data.user) this.setStoredUser(data.user, sessionToken);
		return data;
	},
	async updateUserProfile(userId, updates) {
		const sessionToken = this.getStoredSessionToken();
		const data = await (await apiFetch(`/api/user/${userId}`, {
			method: "PUT",
			headers: {
				"Content-Type": "application/json",
				"x-session-token": sessionToken
			},
			body: JSON.stringify(updates)
		})).json();
		if (!data.success) throw new Error(data.message || "Failed to update profile");
		if (data.user) this.setStoredUser(data.user, sessionToken);
		return data.user;
	},
