function showToast(message, type = "success", title, duration = 3500) {
	if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("esp-toast", { detail: {
		id: `toast-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
		title,
		message,
		type,
		duration
	} }));
}
